SELECT seat_id AS seatId, seat_grade AS seatGrade, block_cd AS blockCd, floor AS floor, row_no AS rowNo, seat_no AS seatNo, seat_status AS seatStatus FROM tb_goods_seatassign_details WHERE sales_id = #{salesId}
AND seat_grade = #{seatGrade}
AND block_cd = #{blockCd}
ORDER BY block_cd, floor, row_no, CAST(seat_no AS UNSIGNED), seat_no
